//! Replay of the original `URenderDevice::Draw3DLine` (UnCamera.cpp:195-263, via the non-virtual
//! `URenderDevice::Draw3DLine` on a calloc'd device) against `fixtures/camera_draw_3d_line.txt`,
//! generated by `Build/camera_fixture_harness/gen_camera.sh`. Each case runs ComputeRenderSize on an
//! identity frame, then plans Draw3DLine; the resulting native submissions are compared
//! bit-for-bit (`line` = color×4, flags, p1×3, p2×3; `point` = color×4, flags, x1, y1, x2, y2, z).

use std::collections::HashMap;
use std::ffi::c_void;

use hp2_abi::engine::generated::{APlayerPawn, FSceneNode, UClient, UViewport};
use hp2_abi::{FCoords, FPlane, FVector};
use hp2_engine::camera::{CameraLinePlan, CameraServices, compute_render_size, plan_3d_line};

const FIXTURE: &str = include_str!("fixtures/camera_draw_3d_line.txt");
const CASES: usize = 96;
const BRANCHES: [&str; 6] = [
    "ortho_line",
    "ortho_dot",
    "ortho_dot_hidden",
    "persp_line",
    "persp_near_p1",
    "persp_discard",
];

unsafe extern "C" fn record_set_scene(_render_dev: *mut c_void, _frame: *mut c_void) {}

fn record_plan(plan: CameraLinePlan, color: FPlane) -> Vec<(u8, Vec<u32>)> {
    if plan.kind == 0 {
        return Vec::new();
    }
    let mut words = vec![
        color.x.to_bits(),
        color.y.to_bits(),
        color.z.to_bits(),
        color.w.to_bits(),
        plan.flags,
        plan.p1.x.to_bits(),
        plan.p1.y.to_bits(),
    ];
    let kind = match plan.kind {
        1 => {
            words.extend([
                plan.p1.z.to_bits(),
                plan.p2.x.to_bits(),
                plan.p2.y.to_bits(),
                plan.p2.z.to_bits(),
            ]);
            0
        }
        2 => {
            words.extend([
                plan.p2.x.to_bits(),
                plan.p2.y.to_bits(),
                plan.p1.z.to_bits(),
            ]);
            1
        }
        other => panic!("invalid native line plan kind {other}"),
    };
    vec![(kind, words)]
}

/// Fail-fast filler for every other services entry; the draw path must never reach it.
unsafe extern "C" fn unexpected_service() {
    panic!("draw_3d_line reached an unexpected CameraServices entry");
}

fn services() -> CameraServices {
    const WORDS: usize = std::mem::size_of::<CameraServices>() / std::mem::size_of::<usize>();
    let filler = unexpected_service as unsafe extern "C" fn() as usize;
    let table: [usize; WORDS] = [filler; WORDS];
    let mut svc: CameraServices = unsafe { std::mem::transmute(table) };
    svc.render_dev_set_scene_node = checked_render_dev_set_scene_node;
    svc
}

fn hex_f32(s: &str) -> f32 {
    f32::from_bits(u32::from_str_radix(s, 16).expect("hex float bits"))
}

fn hex_words(s: &str) -> Vec<u32> {
    s.split(',')
        .map(|w| u32::from_str_radix(w, 16).expect("hex word"))
        .collect()
}

struct Case {
    idx: usize,
    branch: String,
    x: i32,
    y: i32,
    map: i32,
    fov: f32,
    zoom: f32,
    color: FPlane,
    p1: FVector,
    p2: FVector,
}

fn parse_case(line: &str) -> Case {
    let mut it = line.split_whitespace();
    assert_eq!(it.next(), Some("case"));
    assert_eq!(it.next(), Some("draw3d"));
    let idx: usize = it.next().expect("idx").parse().expect("idx parses");
    let kv: HashMap<&str, &str> = it.map(|t| t.split_once('=').expect("key=value")).collect();
    let color = hex_words(kv["color"]);
    let p1 = hex_words(kv["p1"]);
    let p2 = hex_words(kv["p2"]);
    let f = |w: u32| f32::from_bits(w);
    Case {
        idx,
        branch: kv["branch"].to_string(),
        x: kv["x"].parse().expect("x"),
        y: kv["y"].parse().expect("y"),
        map: kv["map"].parse().expect("map"),
        fov: hex_f32(kv["fov"]),
        zoom: hex_f32(kv["zoom"]),
        color: FPlane {
            x: f(color[0]),
            y: f(color[1]),
            z: f(color[2]),
            w: f(color[3]),
        },
        p1: FVector {
            x: f(p1[0]),
            y: f(p1[1]),
            z: f(p1[2]),
        },
        p2: FVector {
            x: f(p2[0]),
            y: f(p2[1]),
            z: f(p2[2]),
        },
    }
}

/// Runs one case and returns the recorded calls.
fn run_case(svc: &CameraServices, c: &Case) -> Vec<(u8, Vec<u32>)> {
    let mut actor: APlayerPawn = unsafe { std::mem::zeroed() };
    actor.rend_map = c.map;
    actor.base.fov_angle = c.fov;
    actor.base.ortho_zoom = c.zoom;
    let mut vp: UViewport = unsafe { std::mem::zeroed() };
    let mut render_dev = 0u8;
    vp.actor = (&mut actor as *mut APlayerPawn).cast();
    vp.ren_dev = (&mut render_dev as *mut u8).cast();
    let mut client: UClient = unsafe { std::mem::zeroed() };
    vp.outer = (&mut client as *mut UClient).cast();
    let identity = FCoords {
        origin: FVector {
            x: 0.0,
            y: 0.0,
            z: 0.0,
        },
        x_axis: FVector {
            x: 1.0,
            y: 0.0,
            z: 0.0,
        },
        y_axis: FVector {
            x: 0.0,
            y: 1.0,
            z: 0.0,
        },
        z_axis: FVector {
            x: 0.0,
            y: 0.0,
            z: 1.0,
        },
    };
    let mut node: FSceneNode = unsafe { std::mem::zeroed() };
    node.viewport = (&mut vp as *mut UViewport).cast();
    node.x = c.x;
    node.y = c.y;
    node.coords = identity;
    node.uncoords = identity;

    let frame: *mut FSceneNode = &mut node;
    unsafe {
        compute_render_size(svc, frame).expect("checked replay callback");
        let plan = plan_3d_line(frame, 0, c.p1, c.p2);
        record_plan(plan, c.color)
    }
}

#[test]
fn draw_3d_line_matches_original() {
    let lines: Vec<&str> = FIXTURE.lines().collect();
    let svc = services();
    let mut per_branch: HashMap<String, usize> = HashMap::new();
    let mut i = 0;
    let mut cases = 0;
    while i < lines.len() {
        let c = parse_case(lines[i]);
        assert!(
            BRANCHES.contains(&c.branch.as_str()),
            "case {}: branch {}",
            c.idx,
            c.branch
        );
        let n: usize = lines[i + 1]
            .strip_prefix("calls ")
            .expect("calls line")
            .parse()
            .expect("call count");
        let want: Vec<(u8, Vec<u32>)> = lines[i + 2..i + 2 + n]
            .iter()
            .map(|l| {
                let (kind, rest) = if let Some(r) = l.strip_prefix("line ") {
                    (0u8, r)
                } else {
                    (
                        1u8,
                        l.strip_prefix("point ")
                            .unwrap_or_else(|| panic!("call line: {l}")),
                    )
                };
                let w: Vec<u32> = rest
                    .split_whitespace()
                    .map(|x| u32::from_str_radix(x, 16).expect("call word"))
                    .collect();
                (kind, w)
            })
            .collect();
        // Structural expectations per branch: hidden dot and near-plane discard draw nothing.
        match c.branch.as_str() {
            "ortho_dot" => assert!(want.iter().all(|(k, _)| *k == 1), "case {}", c.idx),
            "ortho_dot_hidden" | "persp_discard" => assert_eq!(n, 0, "case {}", c.idx),
            _ => {}
        }
        let got = run_case(&svc, &c);
        assert_eq!(
            got.len(),
            want.len(),
            "case {} ({}) call count",
            c.idx,
            c.branch
        );
        for (k, ((gk, gw), (wk, ww))) in got.iter().zip(&want).enumerate() {
            assert_eq!(gk, wk, "case {} call {k} kind", c.idx);
            assert_eq!(gw, ww, "case {} call {k} words", c.idx);
        }
        *per_branch.entry(c.branch.clone()).or_default() += 1;
        cases += 1;
        i += 2 + n;
    }
    assert_eq!(cases, CASES, "case count");
    for b in BRANCHES {
        assert_eq!(per_branch.get(b).copied(), Some(16), "branch {b} count");
    }
}

unsafe extern "C" fn checked_render_dev_set_scene_node(
    _render_dev: *mut c_void,
    _frame: *mut c_void,
) -> i32 {
    unsafe {
        record_set_scene(_render_dev, _frame);
    }
    0
}
